# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: how a value's type is shown to people: "list[DailyClose]", and for a pydantic
#          model the class itself as Python code, shown when its name is hovered
#          (assets/typehover.js).
#          The code is the class as written: kept on the class when a cell or "/assign" defines
#          it (keep_class_sources), read from its file for library classes, else rebuilt from
#          its fields.
# Usage: type_parts(value) -> {"text", "pre", "model", "post", "code", "html"};
#        render.type_label shows it.
# ---------------------------------------------------------------------------
from __future__ import annotations

import ast
import contextlib
import inspect
import re
import textwrap
from typing import Any

from pydantic import BaseModel
from pydantic_core import PydanticUndefined
from pygments import highlight
from pygments.formatters import HtmlFormatter
from pygments.lexers import PythonLexer

MAX_ITEM_TYPES = 3  # a list of more kinds of items than this is shown as a plain "list"
# the class's lines as written, set on a class a cell or "/assign" defined (keep_class_sources)
SOURCE_ATTR = "__ds_source__"
# a type with no model in it: all of it is `pre`
NO_TYPE = {"text": "", "pre": "", "model": "", "post": "", "code": "", "html": ""}


def type_text(value: Any) -> str:
    """A value's type for people: its class name, and for a list what it holds too:
    list[DailyClose], list[float | int]; a plain "list" when empty or too mixed to say.
    """
    name = type(value).__name__
    if not isinstance(value, list) or not value:
        return name
    items = sorted({type(item).__name__ for item in value})
    return f"{name}[{' | '.join(items)}]" if len(items) <= MAX_ITEM_TYPES else name


def type_parts(value: Any) -> dict[str, str]:
    """type_text cut around the pydantic model it names, for a hover on the name only:
    {"text": "list[DailyClose]", "pre": "list[", "model": "DailyClose", "post": "]",
    "code": "class DailyClose(BaseModel, frozen=True): ...", "html": the code highlighted}.
    Without a model (a str, a DataFrame, a list of mixed classes) it is all `pre`, and model,
    code and html are "".
    """
    text = type_text(value)
    model: type[BaseModel] | None = None
    pre = post = ""
    one_class = isinstance(value, list) and value and len({type(item) for item in value}) == 1
    if isinstance(value, BaseModel):
        model = type(value)
    elif one_class and isinstance(value[0], BaseModel):
        model, pre, post = type(value[0]), "list[", "]"
    if model is None:
        return {**NO_TYPE, "text": text, "pre": text}
    code = class_code(model)
    return {"text": text, "pre": pre, "model": model.__name__, "post": post, "code": code, "html": code_html(code)}


def code_html(code: str) -> str:
    """Python code as highlighted HTML: escaped text in <span class="py-k"> (keyword), "py-c1"
    (comment) and so on (Pygments' short token names), coloured by app.css as the cell editor
    colours code.
    """
    return highlight(code, PythonLexer(), HtmlFormatter(nowrap=True, classprefix="py-")).rstrip("\n")


def keep_class_sources(code: str, namespace: dict[str, Any]) -> None:
    """After `code` ran in `namespace`: put each class it defined at the top level on that
    class as written (SOURCE_ATTR: its lines, decorators and comments included), since
    Python can't find the source of a class defined by exec'd code.
    """
    try:
        tree = ast.parse(code)
    except SyntaxError:
        return
    lines = code.splitlines()
    for node in tree.body:
        held = namespace.get(node.name) if isinstance(node, ast.ClassDef) else None
        if isinstance(held, type):
            start = min([node.lineno, *(decorator.lineno for decorator in node.decorator_list)])
            with contextlib.suppress(AttributeError, TypeError):  # a class that refuses attributes
                setattr(held, SOURCE_ATTR, "\n".join(lines[start - 1 : node.end_lineno]))


def class_code(model: type[BaseModel]) -> str:
    """The class as Python code: as written when known, else rebuilt from its fields."""
    if written := model.__dict__.get(SOURCE_ATTR):  # its own, not a parent's
        return str(written)
    if model.__module__ != "__main__":  # "__main__": a cell's class, whose file is not its own
        with contextlib.suppress(OSError, TypeError):
            return textwrap.dedent(inspect.getsource(model)).rstrip()
    return rebuilt_code(model)


def rebuilt_code(model: type[BaseModel]) -> str:
    """The class rebuilt from its fields: their types, defaults and descriptions (as comments).
    Comments written in the class itself are lost.
    """
    bases = [base.__name__ for base in model.__bases__]
    if model.model_config.get("frozen"):
        bases.append("frozen=True")
    lines = [f"class {model.__name__}({', '.join(bases)}):"]
    for name, field in model.model_fields.items():
        default = "" if field.default is PydanticUndefined else f" = {field.default!r}"
        comment = f"  # {field.description}" if field.description else ""
        lines.append(f"    {name}: {_annotation_text(field.annotation)}{default}{comment}")
    if not model.model_fields:
        lines.append("    pass")
    return "\n".join(lines)


def _annotation_text(annotation: Any) -> str:
    """An annotation as written in code: date, list[str], int | None (no module prefixes)."""
    if isinstance(annotation, type) and not getattr(annotation, "__args__", None):
        return annotation.__name__
    text = repr(annotation).replace("NoneType", "None")
    return re.sub(r"\b(?:[A-Za-z_]\w*\.)+([A-Za-z_]\w*)", r"\1", text)
